/**
 * Dropdown delle azioni di selezione, ancorato al checkbox principale
 * in intestazione, piu' banda di stato per "mostra solo selezionate".
 *
 * Il menu viene appeso a document.body (stesso approccio di
 * ext.buttons.utils) perche' con scrollX/scrollY l'intestazione vive
 * dentro .dt-scroll-head, che e' in overflow hidden e taglierebbe il drop.
 */
(function registerIlBronzaDatatablesSelection()
{
    if (! window.jQuery || ! $.fn.dataTable || ! $.fn.dataTable.Api)
    {
        setTimeout(registerIlBronzaDatatablesSelection, 100);
        return;
    }

    window.ibDtGetSelectionLabels = function (tableId)
    {
        const stored = (window.__ibDatatableSelectionLabels || {})[tableId] || {};

        return {
            trigger: stored.trigger || 'Azioni di selezione',
            selectFiltered: stored.selectFiltered || 'Seleziona filtrati',
            selectPage: stored.selectPage || 'Seleziona questa pagina',
            selectNone: stored.selectNone || 'Deseleziona tutte',
            outsideFilter: stored.outsideFilter || ':count fuori filtro',
            showSelected: stored.showSelected || 'Mostra solo selezionate',
            disabledHint: stored.disabledHint || 'Stai gia\' vedendo solo le selezionate',
            banner: stored.banner || 'Stai vedendo solo :count righe selezionate',
            bannerShowAll: stored.bannerShowAll || 'Mostra tutte',
        };
    };

    window.ibDtSelectionEnabled = function (tableId)
    {
        return !! (window.__ibDatatableSelectionDropdown || {})[tableId];
    };

    window.ibDtTableIdOf = function (dt)
    {
        const tableNode = dt.table().node();

        return tableNode.id || null;
    };

    /**
     * Con scrollX/scrollY l'intestazione visibile e' quella clonata in
     * .dt-scroll-head: l'originale resta nel body ma nascosta. Iniettare
     * in entrambe produrrebbe due caret e handler doppi.
     */
    window.ibDtSelectionHeaderCell = function (dt)
    {
        const container = $(dt.table().container());
        const scrollHead = container.find('.dt-scroll-head thead tr.columnsintestations th').first();

        if (scrollHead.length)
            return scrollHead;

        return container.find('thead tr.columnsintestations th').first();
    };

    /**
     * Il thead visibile, cioe' il clone in .dt-scroll-head quando c'e'.
     */
    window.ibDtSelectionHead = function (dt)
    {
        const container = $(dt.table().container());
        const scrollHead = container.find('.dt-scroll-head thead');

        if (scrollHead.length)
            return scrollHead;

        return container.find('thead').first();
    };

    /**
     * render.select() disegna il checkbox nella cella che DataTables
     * considera titolo della colonna 0: con tr.mainheader presente e'
     * quella, altrimenti tr.columnsintestations.
     *
     * Va spostato sempre in tr.columnsintestations per due motivi:
     * il bottone "nascondi intestazione raggruppata" mette uk-hidden su
     * tr.mainheader e si porterebbe via il checkbox (con la scelta pure
     * persistita nelle uiSettings), e la posizione deve restare la stessa
     * fra tabelle con e senza intestazione raggruppata.
     *
     * Si sposta il nodo, non lo si ridisegna: i listener legati
     * direttamente all'input viaggiano con lui.
     */
    window.ibDtRelocateSelectAll = function (dt, $cell)
    {
        const $checkbox = window.ibDtSelectionHead(dt)
            .find('tr.mainheader th:first-child input[type="checkbox"]')
            .first();

        if (! $checkbox.length)
            return;

        /* solo l'input: DataTables 2 lo avvolge in div.dt-column-header
           insieme a titolo e ordinamento, che devono restare dove sono */
        $cell.prepend($checkbox);
    };

    /* ===============================
     *  Contatori
     * =============================== */

    /**
     * Quando "solo selezionate" e' attivo il filtro custom in
     * filtering.min.js restringe search:'applied' alle sole righe
     * selezionate, quindi i contatori di "seleziona" perdono senso e le
     * relative voci vengono disabilitate.
     */
    window.ibDtSelectionCounts = function (dt)
    {
        const showSelected = !! dt.getDataAttribute('showSelected');
        const selected = dt.rows({ selected: true }).count();
        const insideFilter = dt.rows({ selected: true, search: 'applied' }).count();

        return {
            showSelected: showSelected,
            filtered: dt.rows({ search: 'applied' }).count(),
            page: dt.rows({ page: 'current', search: 'applied' }).count(),
            selected: selected,
            outsideFilter: showSelected ? 0 : (selected - insideFilter),
        };
    };

    /* ===============================
     *  Voci del menu
     * =============================== */

    function menuItem(label, hint, disabled, handler)
    {
        const li = document.createElement('li');
        const a = document.createElement('a');

        a.href = '#';
        a.className = 'uk-button uk-button-small uk-width-1-1 uk-text-left uk-button-default ib-dt-selection-item';

        const labelEl = document.createElement('span');
        labelEl.textContent = label;
        a.appendChild(labelEl);

        if (hint)
        {
            const hintEl = document.createElement('span');
            hintEl.className = 'uk-text-muted uk-text-small uk-margin-small-left ib-dt-selection-hint';
            hintEl.textContent = hint;
            a.appendChild(hintEl);
        }

        if (disabled)
        {
            a.classList.add('uk-disabled', 'uk-text-muted');
            a.setAttribute('aria-disabled', 'true');
        }
        else
            a.addEventListener('click', function (ev)
            {
                ev.preventDefault();
                ev.stopPropagation();

                handler();
            });

        li.appendChild(a);

        return li;
    }

    function separator()
    {
        const li = document.createElement('li');
        li.className = 'uk-nav-divider';

        return li;
    }

    function checkedItem(label, active, disabled, handler)
    {
        const li = menuItem((active ? '☑ ' : '☐ ') + label, null, disabled, handler);

        if (active)
            li.querySelector('a').classList.add('uk-text-bold');

        return li;
    }

    window.ibDtBuildSelectionMenu = function (dt, tableId, closeDrop)
    {
        const labels = window.ibDtGetSelectionLabels(tableId);
        const counts = window.ibDtSelectionCounts(dt);
        const listEl = document.createElement('ul');

        listEl.className = 'uk-nav uk-dropdown-nav';

        listEl.appendChild(menuItem(
            labels.selectFiltered,
            counts.showSelected ? labels.disabledHint : '(' + counts.filtered + ')',
            counts.showSelected,
            function ()
            {
                dt.rows({ search: 'applied' }).select();
                closeDrop();
            }
        ));

        if ((window.__ibDatatableSelectionPage || {})[tableId])
            listEl.appendChild(menuItem(
                labels.selectPage,
                counts.showSelected ? null : '(' + counts.page + ')',
                counts.showSelected,
                function ()
                {
                    dt.rows({ page: 'current', search: 'applied' }).select();
                    closeDrop();
                }
            ));

        listEl.appendChild(menuItem(
            labels.selectNone,
            counts.outsideFilter > 0 ? labels.outsideFilter.replace(':count', String(counts.outsideFilter)) : null,
            counts.selected === 0,
            function ()
            {
                dt.rows().deselect();
                closeDrop();
            }
        ));

        listEl.appendChild(separator());

        /* con zero selezionate il toggle mostrerebbe una tabella vuota */
        listEl.appendChild(checkedItem(
            labels.showSelected,
            counts.showSelected,
            counts.selected === 0,
            function ()
            {
                closeDrop();

                dt.toggleShowSelected();

                if (dt.getDataAttribute('showSelected'))
                    window.ibDtRefreshShowSelected(dt, null);
                else
                    window.ibDtDisableShowSelected(dt, null);
            }
        ));

        return listEl;
    };

    /* ===============================
     *  Drop UIkit ancorato al caret
     * =============================== */

    window.ibDtOpenSelectionDrop = function (dt, tableId, caretEl)
    {
        if (! window.UIkit || typeof window.UIkit.drop !== 'function')
            return;

        if (caretEl.__ibSelectionDrop)
        {
            caretEl.__ibSelectionDrop.hide(false);
            caretEl.__ibSelectionDrop.$destroy(true);
        }

        if (caretEl.__ibSelectionMenuEl && caretEl.__ibSelectionMenuEl.parentNode)
            caretEl.__ibSelectionMenuEl.parentNode.removeChild(caretEl.__ibSelectionMenuEl);

        const menuEl = document.createElement('div');
        menuEl.className = 'uk-dropdown uk-dropdown-nav ib-dt-selection-menu';
        document.body.appendChild(menuEl);

        function closeDrop()
        {
            if (caretEl.__ibSelectionDrop)
                caretEl.__ibSelectionDrop.hide(false);
        }

        menuEl.appendChild(window.ibDtBuildSelectionMenu(dt, tableId, closeDrop));

        const drop = window.UIkit.drop(menuEl, {
            target: caretEl,
            pos: 'bottom-left',
            mode: 'click',
            animation: 'uk-animation-fade',
            duration: 80,
            boundary: true,
        });

        caretEl.__ibSelectionDrop = drop;
        caretEl.__ibSelectionMenuEl = menuEl;

        drop.show();
    };

    /* ===============================
     *  Caret in intestazione
     * =============================== */

    window.ibDtInjectSelectionCaret = function (dt)
    {
        const tableId = window.ibDtTableIdOf(dt);

        if (! tableId || ! window.ibDtSelectionEnabled(tableId))
            return;

        const $cell = window.ibDtSelectionHeaderCell(dt);

        if (! $cell.length)
            return;

        /* prima del guard sul caret: il checkbox torna in mainheader
           ogni volta che DataTables ridisegna l'intestazione */
        window.ibDtRelocateSelectAll(dt, $cell);

        if ($cell.find('.ib-dt-selection-caret').length)
            return;

        const labels = window.ibDtGetSelectionLabels(tableId);
        const caret = document.createElement('a');

        caret.href = '#';
        caret.className = 'ib-dt-selection-caret';
        caret.setAttribute('uk-tooltip', labels.trigger);
        caret.setAttribute('title', labels.trigger);
        caret.innerHTML = '<i class="fa-solid fa-caret-down" aria-hidden="true"></i>';

        caret.addEventListener('click', function (ev)
        {
            ev.preventDefault();
            ev.stopPropagation();

            window.ibDtOpenSelectionDrop(dt, tableId, caret);
        });

        $cell.addClass('ib-dt-selection-header').get(0).appendChild(caret);
    };

    /* ===============================
     *  Banda di stato
     * =============================== */

    window.ibDtEnsureSelectionBanner = function (dt, tableId)
    {
        const container = dt.table().container();
        const existing = $(container.parentNode).children('.ib-dt-selection-banner[data-tableid="' + tableId + '"]').get(0);

        if (existing)
            return existing;

        const banner = document.createElement('div');

        banner.className = 'ib-dt-selection-banner uk-alert uk-alert-primary uk-margin-remove-top uk-margin-small-bottom';
        banner.setAttribute('data-tableid', tableId);
        banner.hidden = true;

        container.parentNode.insertBefore(banner, container);

        return banner;
    };

    window.ibDtSyncSelectionBanner = function (dt)
    {
        const tableId = window.ibDtTableIdOf(dt);

        if (! tableId || ! window.ibDtSelectionEnabled(tableId))
            return;

        const banner = window.ibDtEnsureSelectionBanner(dt, tableId);

        if (! dt.getDataAttribute('showSelected'))
        {
            banner.hidden = true;
            banner.innerHTML = '';

            return;
        }

        const labels = window.ibDtGetSelectionLabels(tableId);
        const count = dt.rows({ selected: true }).count();

        banner.hidden = false;
        banner.innerHTML = '<span class="ib-dt-selection-banner-text"></span> <a href="#" class="ib-dt-selection-banner-showall"></a>';
        banner.querySelector('.ib-dt-selection-banner-text').textContent = labels.banner.replace(':count', String(count));
        banner.querySelector('.ib-dt-selection-banner-showall').textContent = labels.bannerShowAll;
    };

    $(document).on('click', '.ib-dt-selection-banner-showall', function (e)
    {
        e.preventDefault();

        const tableId = $(this).closest('.ib-dt-selection-banner').data('tableid');
        const dt = $('#' + tableId).DataTable();

        window.ibDtDisableShowSelected(dt, null);
        window.ibDtSyncSelectionBanner(dt);
    });

    /* ===============================
     *  Aggancio agli eventi DataTables
     * =============================== */

    $(document).on('init.dt.ibSelection draw.dt.ibSelection column-sizing.dt.ibSelection', function (e, settings)
    {
        const dt = new $.fn.dataTable.Api(settings);

        window.ibDtInjectSelectionCaret(dt);
        window.ibDtSyncSelectionBanner(dt);
    });

    $(document).on('select.dt.ibSelection deselect.dt.ibSelection', function (e, dt)
    {
        window.ibDtSyncSelectionBanner(dt);
    });

})();
